    public static void ligar() { System.out.print("A"); }
    public void operar() { System.out.print("1"); }
}
class Modulo extends Aparelho {
    public static void ligar() { System.out.print("M"); }
    public void operar() { System.out.print("2"); }
}
// Trecho executado:
Aparelho obj = new Modulo();
obj.ligar();
obj.operar();

